# Revisão editorial. A redação adaptada é identificada na interface.
PATCHES={}
def patch(key,n,text=None,options=None,support=None,page=None):
 PATCHES.setdefault(key,{})[n]={k:v for k,v in dict(text=text,options=options.split('|') if isinstance(options,str) else options,support=support,page=page).items() if v is not None}
